//! nemo-test-harness: test-evaluation => property_transform_eval_tests
//! Property-transform routing provider (D30/#2075): oracle against the
//! JavaScript in `src/js/motion.js`.
//!
//! Generated by `gen.mjs` (sha256 aa02dbc03b07c788ada392c40af90f001d901fd1f3305b4dc80d211caf7e5173) from the VERBATIM function text
//! of `src/js/motion.js` (git blob 90503c39 at df64f6f5), sliced by name and
//! run under Node v22.22.0 (V8) with `valueAtFrame`, `composeChainTransform`,
//! `legacyParentChainMats`, `computeMotionMat`, `sampleFollowPathAt`, Paper's
//! `Path` and the layer list stubbed per row. Line ranges: `rotPt` 2895-2900,
//! `rotVec` 2901-2905, `transformSegments` 5158-5167, `lerpAngleDeg` 3754,
//! `sampleFollowPathAt` 3470-3511, `layerMotionAt` 3512-3550,
//! `weightedParentsOf` 3824-3837 (`parentWeightKeyFor` 3823),
//! `blendWeighted` 3838-3861, `blendedAncestorMat` 3862-3879,
//! `parentChainMats` 3970-3977. Values are IEEE 754 bit patterns in hex; `-`
//! is null/undefined, `~` the empty string, `!` a null array entry, `u`/`z` a
//! sample that is `undefined`/`[]`.
//!
//! Rows: `wp` (weightedParentsOf), `bam` (blendedAncestorMat), `pcm`
//! (parentChainMats), `fp` (the follow-path block of layerMotionAt) and
//! `fpo` (the clamp and angle steps of sampleFollowPathAt). The oracle rows live in
//! `fixtures/property-transform-eval/oracle.txt`; hand-written controls are
//! in `property_transform_eval_controls.rs`.

use crate::evaluation::motion_parent_chain::{ChainEntry, MotionMat};
use crate::evaluation::property_transform_eval::{
    apply_follow_path, blended_ancestor_mat, follow_path_offset, follow_path_points,
    follow_path_sample, parent_chain_mats, weighted_parents_of, PathSample,
};
use crate::property_transform_eval_controls_tests::{
    extras, sample, table, uid, weights, Mutation,
};

/// Bit pattern for comparison, with every NaN folded to one value; -0 and
/// +0 stay distinct.
fn bits(x: f64) -> u64 {
    if x.is_nan() {
        f64::NAN.to_bits()
    } else {
        x.to_bits()
    }
}

/// Exact rows match bit for bit. On `t` rows (cos/sin/atan2, libm-dependent
/// in the last ulp) a value may differ by `TRIG_ULPS` units of roundoff of
/// its own group: rotation-coupled coordinates share one, any other quantity
/// is alone, and an angle's magnitude is at least a half turn as atan2 error
/// is absolute. A real sign, axis, index or order mistake still fails
/// (`mutations_are_detected`).
const TRIG_ULPS: f64 = 4.0;
const ANGLE_FLOOR: f64 = 180.0;
const COND_CAP: f64 = 1e8;

/// A group of `n` coordinates sharing one magnitude, or one angle in degrees.
#[derive(Clone, Copy)]
enum G {
    N(usize),
    Deg,
}
use G::{Deg, N};

const MAT: &[G] = &[N(1), N(1), Deg, N(1), N(1), N(1), N(1), N(1)];

fn magnitude(xs: &[f64]) -> f64 {
    xs.iter()
        .filter(|x| x.is_finite())
        .fold(0.0_f64, |a, x| a.max(x.abs()))
}

/// Compares one oracle row; a mismatch is recorded, not panicked, so the
/// same loop can prove that mutated inputs are rejected.
struct Check {
    trig: bool,
    label: String,
    inexact: usize,
    worst_ulps: f64,
    bad: Option<String>,
}

impl Check {
    fn new(row: &str, line_no: usize) -> Check {
        Check {
            trig: row.split(' ').nth(1) == Some("t"),
            label: format!("line {}: {}", line_no + 1, &row[..row.len().min(160)]),
            inexact: 0,
            worst_ulps: 0.0,
            bad: None,
        }
    }

    fn fail(&mut self, what: String) {
        if self.bad.is_none() {
            self.bad = Some(format!("{}: {what}", self.label));
        }
    }

    fn group_at(&mut self, actual: &[f64], expected: &[f64], floor: f64) {
        if actual.len() != expected.len() {
            return self.fail(format!("{actual:?} vs {expected:?}"));
        }
        let mag = magnitude(expected).max(magnitude(actual)).max(floor);
        for (&a, &e) in actual.iter().zip(expected) {
            if bits(a) == bits(e) {
                continue;
            }
            // A signed-zero mismatch is never a rounding difference.
            if self.trig && a.is_finite() && e.is_finite() && a != e {
                let ulps = (a - e).abs() / (mag.max(f64::MIN_POSITIVE) * f64::EPSILON);
                self.worst_ulps = self.worst_ulps.max(ulps);
                if ulps <= TRIG_ULPS {
                    self.inexact += 1;
                    continue;
                }
            }
            self.fail(format!("{a:?} != {e:?}"));
        }
    }

    fn v(&mut self, actual: &[f64], expected: &[f64]) {
        self.group_at(actual, expected, 0.0);
    }

    fn deg(&mut self, actual: f64, expected: f64) {
        self.group_at(&[actual], &[expected], ANGLE_FLOOR);
    }

    /// Bit-exact, whatever the row kind (no trig tolerance).
    fn exact(&mut self, actual: f64, expected: f64) {
        if bits(actual) != bits(expected) {
            self.fail(format!("{actual:?} != {expected:?}"));
        }
    }

    /// An angle read from the difference of two transformed points: their
    /// roundoff, relative to the coordinate magnitude, is amplified by
    /// `magnitude / |difference|` (a collapsed tangent is ill-conditioned).
    /// The factor is capped at `COND_CAP` so a near-collapsed tangent cannot
    /// widen the bound without limit; a zero difference counts as 1.
    fn deg_cond(&mut self, actual: f64, expected: f64, cond: f64) {
        let cond = cond.clamp(1.0, COND_CAP);
        self.group_at(&[actual], &[expected], ANGLE_FLOOR * cond);
    }

    fn split(&mut self, actual: &[f64], expected: &[f64], groups: &[G]) {
        if actual.len() != expected.len() {
            return self.fail(format!("{actual:?} vs {expected:?}"));
        }
        let mut at = 0;
        for g in groups {
            match *g {
                N(n) => self.v(&actual[at..at + n], &expected[at..at + n]),
                Deg => self.deg(actual[at], expected[at]),
            }
            at += if let N(n) = *g { n } else { 1 };
        }
    }

    fn opt(&mut self, actual: Option<Vec<f64>>, expected: Option<Vec<f64>>, groups: &[G]) {
        match (actual, expected) {
            (Some(a), Some(e)) => self.split(&a, &e, groups),
            (None, None) => {}
            (a, e) => self.fail(format!("{a:?} vs {e:?}")),
        }
    }

    fn chain(&mut self, actual: &[ChainEntry], expected: &str) {
        let want: Vec<&str> = if expected == "-" {
            Vec::new()
        } else {
            expected.split(';').collect()
        };
        if actual.len() != want.len() {
            return self.fail(format!("{} entries, want {}", actual.len(), want.len()));
        }
        for (e, w) in actual.iter().zip(want) {
            let (m, p) = w.split_once('/').expect("mat/pivot");
            self.split(&mat_vec(Some(e.mat)).expect("mat"), &list(m), MAT);
            self.v(&e.pivot, &list(p));
        }
    }
}

pub(crate) fn hex(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).expect("hex bits"))
}

pub(crate) fn list(token: &str) -> Vec<f64> {
    token.split(',').map(hex).collect()
}

fn maybe(token: &str) -> Option<Vec<f64>> {
    (token != "-").then(|| list(token))
}

pub(crate) fn mat(token: &str) -> Option<MotionMat> {
    maybe(token).map(|v| MotionMat {
        dx: v[0],
        dy: v[1],
        rot: v[2],
        sx: v[3],
        sy: v[4],
        op: v[5],
        ax: v[6],
        ay: v[7],
    })
}

fn mat_vec(m: Option<MotionMat>) -> Option<Vec<f64>> {
    m.map(|m| vec![m.dx, m.dy, m.rot, m.sx, m.sy, m.op, m.ax, m.ay])
}

pub(crate) const ORACLE: &str = include_str!("fixtures/property-transform-eval/oracle.txt");

#[derive(Default)]
pub(crate) struct Run {
    rows: usize,
    exact_rows: usize,
    inexact: usize,
    worst_ulps: f64,
    pub(crate) bad: Vec<String>,
}

pub(crate) fn run(m: Mutation) -> Run {
    let mut r = Run::default();
    for (line_no, row) in ORACLE.lines().enumerate() {
        let t: Vec<&str> = row.split(' ').collect();
        let mut c = Check::new(row, line_no);
        match t[0] {
            "wp" => {
                let ex = extras(t[5]);
                let got = weighted_parents_of(
                    uid(t[2]),
                    uid(t[3]),
                    m.blend(sample(t[4])),
                    &ex,
                    &m.weights(&ex, &weights(t[6])),
                );
                match (got, t[7]) {
                    (None, "-") => {}
                    (Some(parts), exp) if exp != "-" => {
                        let want: Vec<&str> = exp.split(';').collect();
                        if parts.len() != want.len() {
                            c.fail(format!("{} parts, want {}", parts.len(), want.len()));
                        } else {
                            for (p, w) in parts.iter().zip(want) {
                                let (u, wt) = w.rsplit_once(':').expect("uid:weight");
                                if p.uid != uid(u) {
                                    c.fail(format!("uid {:?}, want {u}", p.uid));
                                }
                                c.v(&[p.weight], &[hex(wt)]);
                            }
                        }
                    }
                    (g, e) => c.fail(format!("{g:?} vs {e}")),
                }
            }
            "bam" | "pcm" => {
                let ex = extras(t[5]);
                let w = m.weights(&ex, &weights(t[6]));
                let poses = table(t[7]);
                let calls = std::cell::Cell::new(0_usize);
                let blended = || {
                    blended_ancestor_mat(
                        uid(t[2]),
                        uid(t[3]),
                        m.blend(sample(t[4])),
                        &ex,
                        &w,
                        |u| {
                            calls.set(calls.get() + 1);
                            poses.get(u).copied()
                        },
                    )
                };
                if t[0] == "bam" {
                    c.opt(mat_vec(blended()), maybe(t[8]), MAT);
                    // compose runs exactly as often as in JavaScript.
                    if calls.get().to_string() != t[9] {
                        c.fail(format!("{} compose calls, want {}", calls.get(), t[9]));
                    }
                } else {
                    let legacy = || m.chain(t[8]);
                    let out = parent_chain_mats(m.uid_b(uid(t[3])), blended, legacy);
                    c.chain(&out, t[9]);
                }
            }
            "fp" => {
                let (en, align) = (t[2] == "1", (t[6] == "1") != (m == Mutation::Align));
                let s = maybe(t[4]).map(|v| PathSample {
                    x: v[0],
                    y: v[1],
                    angle: v[2],
                });
                let centre = maybe(t[5]).map(|v| {
                    if m == Mutation::Axis {
                        [v[1], v[0]]
                    } else {
                        [v[0], v[1]]
                    }
                });
                let out =
                    apply_follow_path(mat(t[3]), s.filter(|_| en), centre, align, sample(t[7]));
                c.opt(mat_vec(out), maybe(t[8]), MAT);
            }
            "fpo" => {
                let len = hex(t[2]);
                let pct = sample(t[3]) + f64::from(u8::from(m == Mutation::Percent));
                match (follow_path_offset(pct, len), t[9]) {
                    (None, "-") => {}
                    (Some(off), exp) if exp != "-" => {
                        let pt = list(t[4]);
                        let tan = maybe(t[5]).map(|v| {
                            let y = [v[1], -v[1]][usize::from(m == Mutation::Sign)];
                            [v[0], y]
                        });
                        let centre = maybe(t[7]);
                        let target = mat(t[6])
                            .zip(centre.clone())
                            .map(|(mm, c)| (m.rot(mm), [c[0], c[1]]));
                        let chain = m.chain(t[8]);
                        let at = [pt[0], pt[1]];
                        let s = follow_path_sample(at, tan, target, &chain);
                        let [p, q] = follow_path_points(at, tan, target, &chain);
                        c.exact(off, hex(exp));
                        let want = list(t[10]);
                        c.v(&[s.x, s.y], &want[..2]);
                        // Coordinate scale: every input and output position.
                        let mut scale = magnitude(&[p[0], p[1], q[0], q[1], pt[0], pt[1]]);
                        scale = scale.max(magnitude(&centre.unwrap_or_default()));
                        for e in &chain {
                            scale = scale.max(magnitude(&e.pivot));
                        }
                        let d = ((q[0] - p[0]).powi(2) + (q[1] - p[1]).powi(2)).sqrt();
                        c.deg_cond(s.angle, want[2], if d > 0.0 { scale / d } else { 1.0 });
                    }
                    (g, e) => c.fail(format!("{g:?} vs {e}")),
                }
            }
            op => panic!("unknown oracle op {op}"),
        }
        r.rows += 1;
        r.exact_rows += usize::from(c.inexact == 0 && c.bad.is_none());
        r.inexact += c.inexact;
        r.worst_ulps = r.worst_ulps.max(c.worst_ulps);
        r.bad.extend(c.bad);
    }
    r
}

#[test]
fn generated_oracle_matches_javascript() {
    let r = run(Mutation::None);
    assert!(
        r.bad.is_empty(),
        "{} rows differ:\n{}",
        r.bad.len(),
        r.bad.join("\n")
    );
    assert_eq!(r.rows, 1090, "oracle row count");
    println!(
        "property transform oracle: {}/{} rows bit-exact, {} bounded values, worst {:.3} group ulps",
        r.exact_rows, r.rows, r.inexact, r.worst_ulps
    );
}
